parameters.jsCode:
// Prepare prompt based on received Moodle mod_cv payload
const body = $input.item.json.body || $input.item.json;
const exam = body.exam || { type: 'PMP', contact_hours: 35 };
const candidate = body.candidate || {};
const projects = body.projects || [];

const systemPrompt = `You are a certified PMI Application Specialist and PMBOK expert.
Your goal is to format candidate project experience into official PMI application descriptions for ${exam.type.toUpperCase()}.

Rules:
1. Use first-person singular ('I led', 'I managed', 'I directed'). Never use third-person.
2. Structure each project description strictly into:
   - Objective: (1-2 sentences on project purpose and business goal)
   - Outcome: (1-2 sentences on project result and deliverables handed over)
   - Role: (1 sentence on your leadership role)
   - Responsibilities: Initiating (charter, stakeholders), Planning (WBS, schedule, budget, risks), Executing (team leadership, deliverables), Monitoring & Controlling (EVM, KPIs, change management), Closing (lessons learned, project closure).
3. Keep word count strictly between 200 and 450 words per project.
4. Avoid operational/routine wording. Align with PMBOK Guide terminology.
5. Output must be strictly valid JSON without markdown wrapping.`;

const userPrompt = `Candidate Name: ${candidate.name}\nTarget Certification: ${exam.type}\nContact Hours: ${exam.contact_hours}\n\nProjects to format:\n` + JSON.stringify(projects, null, 2);

return [{
  json: {
    systemPrompt,
    userPrompt,
    originalData: body
  }
}];

parameters.responseBody:
={
  "summary": "Certified professional with comprehensive project leadership experience aligned with " + ($json.originalData.exam.type ? $json.originalData.exam.type.toUpperCase() : 'PMI') + " standards and " + ($json.originalData.exam.contact_hours || 35) + " hours of formal education.",
  "projects": $json.originalData.projects.map((p, i) => ({
    "title": p.title,
    "role": p.role,
    "methodology": p.methodology,
    "formatted_description": "IN: Identified key stakeholders and developed the project charter for " + p.title + ".\nPL: Created the Work Breakdown Structure (WBS), risk register, and schedule.\nEX: Directed cross-functional team execution and managed resource allocation.\nMC: Monitored KPIs, managed change requests, and tracked budget variance.\nCL: Facilitated formal lessons-learned workshop and closed administrative procurements.\nOutcome: Successfully delivered deliverables meeting baseline requirements."
  }))
}
